import requests

def scrape_shopify_shops(url):
    html = requests.get(url).text
    shops = []

    # Extract shops from HTML
    start_tag = '<li>'
    end_tag = '</li>'

    shops_html = html.split(start_tag)[1:]

    for shop_html in shops_html:
        if end_tag in shop_html:
            shop_html = shop_html.split(end_tag)[0]
            shop = parse_shop_html(shop_html)
            shops.append(shop)

    return shops

def parse_shop_html(shop_html):
    name = extract_text(shop_html, 'h3')
    products = extract_products(shop_html)

    return {'name': name, 'products': products}

def extract_text(html, tag):
    return ' '.join(html.split(tag)[1].split('</')[0:1])

def extract_products(html):
    products = []
    start_tag = '<li>'
    end_tag = '</li>'

    products_html = html.split(start_tag)

    for product_html in products_html:
        if 'product' in product_html and end_tag in product_html:
            product_html = product_html.split(end_tag)[0]
            products.append(parse_product(product_html))

    return products

def parse_product(html):
    name = extract_text(html, 'h4')

    return {'name': name}

