from itertools import permutations

def schedule_meeting(attendees):
    total_schedule = []

    for p in permutations(attendees):
        total_schedule.append(p)

    for i, (attendee1, attendee2) in enumerate(zip(attendees, attendees[1:])):
        print(f"Meeting between {attendee1} and {attendee2} at {i * 30 + 60}")

        total_schedule.append((attendee1, attendee2))

