import pickle
from collections import deque

class GenderRoles:
    def __init__(self, roles):
        self.roles = deque(roles)

    def get_role(self):
        return self.roles.popleft()

    def add_role(self, role):
        self.roles.append(role)

    def serialize(self):
        return pickle.dumps(self)

    def deserialize(self, data):
        self.roles = pickle.loads(data).roles

gender_roles = GenderRoles(["breadwinner", "manager"])
pickled_data = gender_roles.serialize()

del gender_roles

