import tarfile
import os

def unpack_tar_file(tar_file):
    tar = tarfile.open(tar_file)
    tar.extractall(path="../")
    tar.close()

def unzip_archive(zip_file):
    if zip_file.endswith('.tar.gz'):
        tar = tarfile.open(zip_file)
        tar.extractall(path="../")
        tar.close()
    elif zip_file.endswith('.tar.bz2'):
        tar = tarfile.open(zip_file, 'r:bz2')
        tar.extractall(path="../")
        tar.close()
    else:
        os.system('tar -xzf ' + zip_file)

def process_archives(archive_paths):
    for archive in archive_paths:
        if archive.endswith('.zip'):
            os.system('unzip ' + archive)
        elif archive.endswith('.tar') or archive.endswith('.tar.gz') or archive.endswith('.tar.bz2'):
            unpack_tar_file(archive)
        else:
            print('Unrecognized archive: ' + archive)

if __name__ == '__main__':
    archive_paths = ['archive.zip', 'backup.tar', 'db.tar.gz']
    process_archives(archive_paths)

